import { createAppointment, createClient, createPayment, createSession, listAppointmentsByDateRange, listClientAppointments, listClientPayments, listClientSessions, listClients, updateAppointment, updateClient, updatePayment, updateSession } from './client-api.js'
import { hasSupabaseConfig } from './supabase.js'

