  const [sessions, setSessions] = useState(demoMode ? demoSessions : []); const [appointments, setAppointments] = useState([]); const [payments, setPayments] = useState(demoMode ? demoPayments : []); const [selectedSession, setSelectedSession] = useState(null); const [selectedAppointment, setSelectedAppointment] = useState(null); const [selectedPayment, setSelectedPayment] = useState(null); const [sessionMode, setSessionMode] = useState(null); const [appointmentMode, setAppointmentMode] = useState(null); const [paymentMode, setPaymentMode] = useState(null)
  const [calendarWeekStart, setCalendarWeekStart] = useState(calendarWeekFromLocation); const [calendarAppointments, setCalendarAppointments] = useState([]); const [calendarLoading, setCalendarLoading] = useState(false); const [calendarMode, setCalendarMode] = useState(null); const [calendarAppointment, setCalendarAppointment] = useState(null); const [calendarRefresh, setCalendarRefresh] = useState(0)
  const [loading, setLoading] = useState(hasSupabaseConfig); const [sessionsLoading, setSessionsLoading] = useState(false); const [saving, setSaving] = useState(false); const [notice, setNotice] = useState(''); const [error, setError] = useState(''); const [query, setQuery] = useState(''); const [status, setStatus] = useState('todos'); const [sort, setSort] = useState({ key: 'nombre', dir: 'asc' }); const search = useRef(null); const heading = useRef(null)
