  useEffect(() => { if (!hasSupabaseConfig) return; let active = true; listClients().then((data) => active && setClients(data)).catch((cause) => active && setError(`No se pudo cargar la lista de clientes. ${cause.message}`)).finally(() => active && setLoading(false)); return () => { active = false } }, [])
  useEffect(() => { if (!selected || !hasSupabaseConfig) return; let active = true; setSessionsLoading(true); setError(''); listClientSessions(selected.id).then((data) => active && setSessions(data)).catch((cause) => active && setError(`No se pudo cargar el historial de sesiones. ${cause.message}`)).finally(() => active && setSessionsLoading(false)); return () => { active = false } }, [selected?.id])
  useEffect(() => { if (!selected || !hasSupabaseConfig) return; let active = true; setSessionsLoading(true); listClientAppointments(selected.id).then((data) => active && setAppointments(data)).catch((cause) => active && setError(`No se pudo cargar la agenda del cliente. ${cause.message}`)).finally(() => active && setSessionsLoading(false)); return () => { active = false } }, [selected?.id])
  useEffect(() => { if (!selected || !hasSupabaseConfig) return; let active = true; setSessionsLoading(true); listClientPayments(selected.id).then((data) => active && setPayments(data)).catch((cause) => active && setError(`No se pudieron cargar los pagos del cliente. ${cause.message}`)).finally(() => active && setSessionsLoading(false)); return () => { active = false } }, [selected?.id])
  useEffect(() => { document.title = `${quickCapture ? 'Captura rápida' : view === 'calendar' ? 'Calendario' : 'Clientes'} · Práctica` }, [quickCapture, view])
  useEffect(() => { if (quickCapture) return; window.history.replaceState(null, '', view === 'calendar' ? `#calendario?week=${calendarWeekStart}` : '#clientes') }, [calendarWeekStart, quickCapture, view])
  useEffect(() => { if (view !== 'calendar' || quickCapture || !hasSupabaseConfig) return; let active = true; setCalendarLoading(true); setError(''); listAppointmentsByDateRange(calendarWeekStart, addDays(calendarWeekStart, 6)).then((data) => active && setCalendarAppointments(data)).catch((cause) => active && setError(`No se pudo cargar el calendario. ${cause.message}`)).finally(() => active && setCalendarLoading(false)); return () => { active = false } }, [calendarRefresh, calendarWeekStart, quickCapture, view])
  const visible = useMemo(() => { const term = query.trim().toLocaleLowerCase('es-PY'); const dir = sort.dir === 'asc' ? 1 : -1; return clients.filter((client) => (status === 'todos' || client.estado === status) && (!term || `${nameOf(client)} ${client.email} ${client.telefono}`.toLocaleLowerCase('es-PY').includes(term))).sort((a, b) => { const primary = sort.key === 'estado' ? (a.estado || '').localeCompare(b.estado || '') : 0; return (primary || nameOf(a).localeCompare(nameOf(b), 'es-PY')) * dir }) }, [clients, query, sort, status])
  const toggleSort = (key) => setSort((current) => current.key === key ? { key, dir: current.dir === 'asc' ? 'desc' : 'asc' } : { key, dir: 'asc' })
  const sortIndicator = (key) => sort.key === key ? (sort.dir === 'asc' ? '▲' : '▼') : '⇅'
  const ariaSortFor = (key) => sort.key === key ? (sort.dir === 'asc' ? 'ascending' : 'descending') : 'none'
  async function saveClient(values) { setSaving(true); setError(''); try { const creating = mode === 'new'; const saved = demoMode ? (creating ? { ...values, id: `demo-${Date.now()}` } : { ...selected, ...values }) : (creating ? await createClient(values) : await updateClient(selected.id, values)); setClients((current) => creating ? [saved, ...current] : current.map((client) => client.id === saved.id ? saved : client)); setMode(null); const returningToForm = creating && (quickCapture || (view === 'calendar' && calendarMode === 'new')); if (returningToForm) { setNewClientId(saved.id); setNotice(demoMode ? 'Cliente agregado solo en la vista de demostración.' : 'Cliente agregado y seleccionado.') } else { setSelected(saved); setNotice(demoMode ? 'Cambio aplicado solo en la vista de demostración.' : creating ? 'Cliente guardado.' : 'Cambios guardados.') } } catch (cause) { setError(`No se pudo guardar el cliente. ${cause.message}`) } finally { setSaving(false) } }
