  async function saveAppointment(values) { setSaving(true); setError(''); try { const creating = appointmentMode === 'new'; const saved = await persistAppointment({ mode: appointmentMode, id: selectedAppointment?.id, values, clientId: selected.id, current: selectedAppointment, demoMode }); setAppointments((current) => creating ? [...current, saved].sort(byDateTime) : current.map((item) => item.id === saved.id ? saved : item)); setAppointmentMode(null); setSelectedAppointment(null); setNotice(creating ? 'Cita guardada.' : 'Cambios guardados.') } catch (cause) { setError(`No se pudo guardar la cita. ${cause.message}`) } finally { setSaving(false) } }
  async function saveCalendarAppointment(values) { setSaving(true); setError(''); try { const creating = calendarMode === 'new'; const weekEnd = addDays(calendarWeekStart, 6); const saved = await persistAppointment({ mode: calendarMode, id: calendarAppointment?.id, values, current: calendarAppointment, demoMode }); if (demoMode) setCalendarAppointments((current) => [...current.filter((item) => item.id !== saved.id), saved].filter((item) => item.fecha >= calendarWeekStart && item.fecha <= weekEnd).sort(byDateTime)); else setCalendarRefresh((current) => current + 1); if (selected?.id === saved.client_id) { if (demoMode) setAppointments((current) => [...current.filter((item) => item.id !== saved.id), saved].sort(byDateTime)); else setAppointments(await listClientAppointments(saved.client_id)) } setCalendarMode(null); setCalendarAppointment(null); setNotice(saved.fecha < calendarWeekStart || saved.fecha > weekEnd ? `Cita guardada para ${dateOf(saved.fecha)}. Navegá a esa semana para verla.` : creating ? 'Cita guardada.' : 'Cambios guardados.') } catch (cause) { setError(`No se pudo guardar la cita. ${cause.message}`) } finally { setSaving(false) } }
